  questions: [
    { n: 1, skill: "Words in Context", texts: [{ body: "The mayor’s promise was ______ until a dollar amount appeared in the budget, not just in a speech." }], prompt: "Which choice completes the text with the most logical and precise word or phrase?", choices: { A: "aspirational", B: "already spent", C: "illegal on its face", D: "rhymed" }, answer: "A", explain: { correct: "Aspirational means hoped-for rather than secured; a speech without a budget line fits.", wrong: { B: "Already spent would mean money moved, unlike a mere speech.", C: "A speech promise is not automatically illegal.", D: "Rhymed is poetic." } } },
    { n: 2, skill: "Words in Context", texts: [{ body: "Researchers ______ pollen from lake mud to reconstruct which trees had stood on the shore a thousand years ago." }], prompt: "Which choice completes the text with the most logical and precise word or phrase?", choices: { A: "extracted", B: "ignored", C: "composed as music", D: "sold as perfume only" }, answer: "A", explain: { correct: "Extracted means taken out; pulling pollen from mud for reconstruction fits.", wrong: { B: "Ignoring pollen would not reconstruct trees.", C: "Music is unrelated.", D: "Perfume is not the scientific aim." } } },
    { n: 3, skill: "Words in Context", texts: [{ body: "The novel’s narrator is ______ of her own charm, which makes the charm more irritating, not less." }], prompt: "Which choice completes the text with the most logical and precise word or phrase?", choices: { A: "conscious", B: "unaware", C: "silent", D: "illiterate" }, answer: "A", explain: { correct: "Conscious of her own charm means she knows it; knowing and still deploying it can irritate.", wrong: { B: "Unaware charm would not be self-aware in the way the sentence describes.", C: "A narrator speaking is not silent.", D: "Illiterate is unrelated." } } },
    { n: 4, skill: "Words in Context", texts: [{ body: "New bike lanes ______ car travel time by under a minute in the study, while injuries at those corners fell sharply." }], prompt: "Which choice completes the text with the most logical and precise word or phrase?", choices: { A: "increased", B: "erased all", C: "set to music", D: "translated" }, answer: "A", explain: { correct: "Increased by under a minute is a small rise in car time beside a sharp injury drop.", wrong: { B: "Under a minute is not erasing all travel time.", C: "Music is unrelated.", D: "Translated is language." } } },
    { n: 5, skill: "Words in Context", texts: [{ body: "His summary ______ a key caveat, so readers thought the drug worked in all ages when it had been tested only in adults." }], prompt: "Which choice completes the text with the most logical and precise word or phrase?", choices: { A: "omitted", B: "emphasized", C: "rhymed", D: "photographed" }, answer: "A", explain: { correct: "Omitted means left out; missing the age caveat caused the overgeneralization.", wrong: { B: "Emphasized would highlight the caveat.", C: "Rhymed is poetic.", D: "Photographed is irrelevant." } } },
    { n: 6, skill: "Words in Context", texts: [{ body: "The two accounts were ______ on the sequence of shots, which allowed investigators to build a single timeline." }], prompt: "Which choice completes the text with the most logical and precise word or phrase?", choices: { A: "aligned", B: "irreconcilable", C: "silent", D: "fictional by agreement" }, answer: "A", explain: { correct: "Aligned means in agreement; matching sequences enabling one timeline fits.", wrong: { B: "Irreconcilable accounts would block a single timeline.", C: "Accounts that give sequences are not silent.", D: "Investigators treat them as usable, not as agreed fiction." } } },
    { n: 7, skill: "Text Structure and Purpose", texts: [{ body: "A “food desert” map that counts stores but not bus lines will misread a neighborhood. Access is a route, not a dot. Put the map on a schedule, or you have drawn shelves without doors." }], prompt: "Which choice best states the main purpose of the text?", choices: { A: "To argue that access maps must include how people actually travel", B: "To sell groceries", C: "To deny that stores exist", D: "To teach desert ecology" }, answer: "A", explain: { correct: "Stores versus bus lines, route not dot, shelves without doors.", wrong: { B: "No grocery ad appears.", C: "Stores are counted as real.", D: "Desert is a metaphor." } } },
    { n: 8, skill: "Text Structure and Purpose", texts: [{ body: "An epilogue that ties every thread can be a gift. It can also be a refusal to let the reader do any remaining work. Closure is a service and a control." }], prompt: "Which choice best describes the function of the last sentence?", choices: { A: "It names the double nature of narrative closure", B: "It lists threads", C: "It bans epilogues", D: "It defines work as employment only" }, answer: "A", explain: { correct: "Service and control compress gift versus refusal to let the reader work.", wrong: { B: "No list appears.", C: "Epilogues can still be gifts.", D: "Work means interpretive labor." } } },
    { n: 9, skill: "Text Structure and Purpose", texts: [{ body: "Write the methods so a rival could copy them. If a rival cannot copy them, you have written a vibe, not a protocol." }], prompt: "Which choice best describes the overall structure of the text?", choices: { A: "A standard for methods, then a diagnosis of writing that fails it", B: "A rivalry as a sports recap", C: "A protocol as a diplomatic treaty only", D: "A recipe for vibes as a product" }, answer: "A", explain: { correct: "Copyable methods versus vibe if they cannot be copied.", wrong: { B: "Rival is scientific, not a game recap.", C: "Protocol means procedure.", D: "Vibe is the failure mode." } } },
    { n: 10, skill: "Cross-Text Connections", texts: [{ label: "Text 1", body: "Urban highways that sliced neighborhoods should be removed and replaced with streets. The original cuts were political, and undoing them is repair." }, { label: "Text 2", body: "Removal without transit capacity can recreate the jam on surface streets that the highway once hid. Repair is not only demolition. It is a network that still moves people who did not choose the original cut." }], prompt: "Text 2 would most likely", choices: { A: "support repair as a goal but insist it include how people still need to move", B: "claim neighborhoods were never sliced", C: "argue that all highways must stay forever unchanged", D: "deny that people travel" }, answer: "A", explain: { correct: "Text 2 says repair is not only demolition and must still move people.", wrong: { B: "Text 2 does not deny the cuts.", C: "Text 2 allows removal if capacity is addressed.", D: "Moving people is Text 2’s concern." } } }
  ]
