    { n: 10, skill: "Cross-Text Connections", texts: [{ label: "Text 1", body: "Public comments at zoning hearings should be first-come, first-served. Any other order lets insiders speak while parents are still parking." }, { label: "Text 2", body: "First-come rewards people with flexible afternoons. A lottery for speaking slots, with a hold for adjacent residents, is less polite and more representative. Parking is real; so is a room already filled by retirees at 2 p.m." }], prompt: "Which choice best describes the difference in fairness?", choices: { A: "Text 1 treats arrival order as fair; Text 2 treats it as biased toward flexible schedules", B: "Text 2 wants no public comment", C: "Text 1 bans adjacent residents", D: "Both ignore parking" }, answer: "A", explain: { correct: "Text 1 defends first-come against insiders; Text 2 says first-come is itself an insider advantage of time.", wrong: { B: "Text 2 still wants speaking slots.", C: "Text 1 worries about parents parking, not banning residents.", D: "Both mention parking." } } }
